class Solution:
    def garbageCollection(self, garbage: list[str], travel: list[int]) -> int:
        pref = [0]
        for t in travel:
            pref.append(pref[-1] + t)

        last_idx = {}
        total_items = 0
        for i, house in enumerate(garbage):
            total_items += len(house)
            for ch in house:
                last_idx[ch] = i

        travel_time = sum(pref[last_idx[ch]] for ch in last_idx)
        return total_items + travel_time

class Solution {
public:
    int garbageCollection(std::vector<std::string>& garbage, std::vector<int>& travel) {
        std::vector<int> pref(garbage.size(), 0);
        for (int i = 0; i < (int)travel.size(); i++) {
            pref[i + 1] = pref[i] + travel[i];
        }
        int lastM = 0, lastP = 0, lastG = 0;
        int totalItems = 0;
        for (int i = 0; i < (int)garbage.size(); i++) {
            totalItems += garbage[i].size();
            for (char ch : garbage[i]) {
                if (ch == 'M') lastM = i;
                else if (ch == 'P') lastP = i;
                else if (ch == 'G') lastG = i;
            }
        }
        return totalItems + pref[lastM] + pref[lastP] + pref[lastG];
    }
};

class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int[] pref = new int[garbage.length];
        for (int i = 0; i < travel.length; i++) {
            pref[i + 1] = pref[i] + travel[i];
        }
        int lastM = 0, lastP = 0, lastG = 0;
        int totalItems = 0;
        for (int i = 0; i < garbage.length; i++) {
            totalItems += garbage[i].length();
            for (char ch : garbage[i].toCharArray()) {
                if (ch == 'M') lastM = i;
                else if (ch == 'P') lastP = i;
                else if (ch == 'G') lastG = i;
            }
        }
        return totalItems + pref[lastM] + pref[lastP] + pref[lastG];
    }
}

